class BriefingsShortcodeRenderer {
    public static function team(array $atts = []): string {
        if (!is_user_logged_in()) return '<p>Por favor, inicia sessão.</p>';
        $id = function_exists('wp_unique_id') ? wp_unique_id('ff-briefings-') : 'ff-briefings-' . wp_rand(1000,9999);
        $clientId = absint($atts['client_id'] ?? ($_GET['client_id'] ?? 0));
        $projectId = absint($atts['project_id'] ?? ($_GET['project_id'] ?? 0));
        ob_start(); ?>
        <?php self::styles(); ?>
        <div class="ff-briefings ff-operational-surface ff-operational-surface-briefings" id="<?php echo esc_attr($id); ?>" data-mode="team" data-user-id="<?php echo esc_attr(get_current_user_id()); ?>" data-client-id="<?php echo esc_attr($clientId); ?>" data-project-id="<?php echo esc_attr($projectId); ?>" data-nonce="<?php echo esc_attr(wp_create_nonce('wp_rest')); ?>" data-api="<?php echo esc_url(rest_url('routespro/v1/')); ?>">
          <?php echo ReactFrontFoundation::operationalModuleMount($id, 'briefings', 'Briefings'); ?>
          <div class="ffb-front-toolbar"><div><span class="ffb-front-kicker">Briefing Hub</span><h3>Prioridades, promoções e instruções das tuas lojas</h3><p>Conteúdo filtrado pelas campanhas e lojas que te estão atribuídas.</p></div><button type="button" class="ffb-front-btn ghost" data-refresh>Atualizar</button></div>
          <div class="ffb-front-status" data-status>A carregar briefings...</div>
          <div class="ffb-front-list" data-list></div>
        </div>
        <?php self::script($id, 'team'); ?>
        <?php return ob_get_clean();
    }

    public static function client(array $atts = []): string {
        if (!is_user_logged_in()) return '<p>Por favor, inicia sessão.</p>';
        $id = function_exists('wp_unique_id') ? wp_unique_id('ff-client-briefings-') : 'ff-client-briefings-' . wp_rand(1000,9999);
        $clientId = absint($atts['client_id'] ?? ($_GET['client_id'] ?? 0));
        $projectId = absint($atts['project_id'] ?? ($_GET['project_id'] ?? 0));
        ob_start(); ?>
        <?php self::styles(); ?>
        <div class="ff-briefings ff-client-briefings ff-operational-surface ff-operational-surface-briefings" id="<?php echo esc_attr($id); ?>" data-mode="client" data-user-id="<?php echo esc_attr(get_current_user_id()); ?>" data-client-id="<?php echo esc_attr($clientId); ?>" data-project-id="<?php echo esc_attr($projectId); ?>" data-nonce="<?php echo esc_attr(wp_create_nonce('wp_rest')); ?>" data-api="<?php echo esc_url(rest_url('routespro/v1/')); ?>">
          <?php echo ReactFrontFoundation::operationalModuleMount($id, 'briefings', 'Briefings'); ?>
          <div class="ffb-front-toolbar"><div><span class="ffb-front-kicker">Prova de comunicação</span><h3>Briefings disponibilizados à operação</h3><p>Consulta o conteúdo publicado e acompanha visualizações e confirmações de leitura.</p></div><button type="button" class="ffb-front-btn ghost" data-refresh>Atualizar</button></div>
          <div class="ffb-front-status" data-status>A carregar briefings...</div>
          <div class="ffb-front-list" data-list></div>
        </div>
        <?php self::script($id, 'client'); ?>
        <?php return ob_get_clean();
    }

