    private static function script(string $id, string $mode): void { ?>
<script>
(function(){
 const root=document.getElementById(<?php echo wp_json_encode($id); ?>);if(!root)return;
 const mode=<?php echo wp_json_encode($mode); ?>,api=root.dataset.api,nonce=root.dataset.nonce,list=root.querySelector('[data-list]'),status=root.querySelector('[data-status]');
 const parentPortal=root.closest('#routespro-client-portal')||document.getElementById('routespro-client-portal');
 const currentScope=()=>{const c=mode==='client'&&parentPortal&&parentPortal.querySelector('#rpcp-client'),p=mode==='client'&&parentPortal&&parentPortal.querySelector('#rpcp-project');const client_id=(c&&c.value)||root.dataset.clientId||'';const project_id=(p&&p.value)||root.dataset.projectId||'';root.dataset.clientId=client_id;root.dataset.projectId=project_id;return{client_id,project_id};};
 const cacheUser=String(root.dataset.userId||'0'),cacheTtl=15*60*1000;
 const cacheKey=()=>{const scope=currentScope();return 'fieldflow_briefings_v2_'+cacheUser+'_'+mode+'_'+(scope.client_id||'all')+'_'+(scope.project_id||'all');};
 const notifyReact=()=>window.dispatchEvent(new CustomEvent('fieldflow:operational-module-refresh',{detail:{rootId:root.id,module:'briefings'}}));
 const esc=s=>(s==null?'':String(s)).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
 const fmtDate=s=>{if(!s)return'';const d=new Date(String(s).replace(' ','T'));return isNaN(d)?esc(s):d.toLocaleDateString('pt-PT')};
 const fmtDateTime=s=>{if(!s)return'';const d=new Date(String(s).replace(' ','T'));return isNaN(d)?esc(s):d.toLocaleString('pt-PT',{dateStyle:'short',timeStyle:'short'})};
 const fmtMoney=n=>Number(n||0).toLocaleString('pt-PT',{style:'currency',currency:'EUR'});
 const labelMap={space:'Espaço',store_type:'Tipo de loja',sales_rep:'Responsável',period:'Período',product_code:'Código',product:'Produto',allocation:'Alocação',actual:'Real',pending:'Pendente'};
 const typeLabels={space:'Espaço centralizado',assortment:'Sortido específico',information:'Informação'};
 const pct=n=>(Number(n||0)*100).toLocaleString('pt-PT',{minimumFractionDigits:1,maximumFractionDigits:1})+'%';
 const pp=n=>{const v=Number(n||0)*100;return (v>0?'+':'')+v.toLocaleString('pt-PT',{minimumFractionDigits:1,maximumFractionDigits:1})+' p.p.'};
 const detailsText=o=>Object.entries(o||{}).filter(([k,v])=>v!==''&&v!=null&&!['product','name','metric','source_row','parser','sheet','source_sheet','source_column','source_file'].includes(k)&&!k.startsWith('_')).map(([k,v])=>esc(labelMap[k]||k.replaceAll('_',' '))+': '+esc(v)).join(' · ');
 async function req(url,opts={}){const r=await fetch(url,Object.assign({credentials:'same-origin',headers:{'X-WP-Nonce':nonce}},opts));const text=await r.text();let data={};try{data=text?JSON.parse(text):{}}catch(_){data={message:text}}if(!r.ok)throw new Error(data.message||'Falha no pedido.');return data;}
 function itemCount(section){return Array.isArray(section?.content?.items)?section.content.items.length:(section?.content?.text?1:0)}
 function sectionHtml(s){const c=s.content||{},items=Array.isArray(c.items)?c.items:[];let body='';
  if(s.type==='promotions'){body='<div class="ffb-table-wrap ffb-responsive-records"><table><thead><tr><th>Produto</th><th>Período</th><th>PVPR</th><th>Desconto</th><th>Promo</th></tr></thead><tbody>'+items.map(i=>'<tr><td><strong>'+esc(i.product)+'</strong></td><td>'+fmtDate(i.valid_from)+' a '+fmtDate(i.valid_to)+'</td><td>'+fmtMoney(i.regular_price)+'</td><td>'+fmtMoney(i.discount)+'</td><td class="ffb-price">'+fmtMoney(i.promo_price)+'</td></tr>').join('')+'</tbody></table><div class="ffb-mobile-records">'+items.map(i=>'<article class="ffb-mobile-record"><strong>'+esc(i.product)+'</strong><div class="ffb-mobile-meta"><span><small>Vigência</small>'+fmtDate(i.valid_from)+' a '+fmtDate(i.valid_to)+'</span><span><small>PVP regular</small>'+fmtMoney(i.regular_price)+'</span><span><small>Desconto</small>'+fmtMoney(i.discount)+'</span><span class="ffb-mobile-price"><small>Preço promocional</small>'+fmtMoney(i.promo_price)+'</span></div></article>').join('')+'</div></div>'; /* 9DL mobile records */}
  else if(s.type==='cardex'){body='<input class="ffb-cardex-search" type="search" placeholder="Pesquisar produto no cardex"><div class="ffb-table-wrap ffb-responsive-records"><table data-cardex><thead><tr><th>Código</th><th>Produto</th><th>Categoria</th><th>Cap.</th><th>UN/CX</th></tr></thead><tbody>'+items.map(i=>'<tr data-search="'+esc(((i.code||'')+' '+(i.product||'')+' '+(i.category||'')).toLowerCase())+'"><td>'+esc(i.code)+'</td><td><strong>'+esc(i.product)+'</strong><br><small>'+esc(i.brand||i.type||'')+'</small></td><td>'+esc(i.category)+'</td><td>'+esc(i.capacity_cl||'')+'</td><td>'+esc(i.units_box||'')+'</td></tr>').join('')+'</tbody></table><div class="ffb-mobile-records">'+items.map(i=>'<article class="ffb-mobile-record" data-search="'+esc(((i.code||'')+' '+(i.product||'')+' '+(i.category||'')).toLowerCase())+'"><strong>'+esc(i.product)+'</strong><div class="ffb-mobile-meta"><span><small>Código</small>'+esc(i.code)+'</span><span><small>Categoria</small>'+esc(i.category)+'</span><span><small>Capacidade</small>'+esc(i.capacity_cl||'')+'</span><span><small>Unidades/cx</small>'+esc(i.units_box||'')+'</span></div></article>').join('')+'</div></div>';} // 9DL mobile cardex labels
  else if(s.type==='share_space'){const ordered=[...items].sort((a,b)=>Number(a.gap||0)-Number(b.gap||0));const below=ordered.filter(i=>Number(i.gap||0)<0).length;body='<div class="ffb-share-intro"><strong>Semana de referência W'+esc(c.week||'')+'</strong><span>'+below+' KPI(s) abaixo do objetivo</span></div><div class="ffb-share-grid">'+ordered.map(i=>{const isBelow=Number(i.gap||0)<0;return '<article class="ffb-share-card '+(isBelow?'below':'ok')+'"><div class="ffb-share-card-head"><strong>'+esc(i.metric)+'</strong><span>'+(isBelow?'Abaixo do objetivo':'Objetivo atingido')+'</span></div><div class="ffb-share-values"><div><small>Quota PR</small><b>'+pct(i.share)+'</b></div><div><small>Quota concorrência</small><b>'+pct(i.competitor_share)+'</b></div><div><small>Objetivo</small><b>'+pct(i.target)+'</b></div><div><small>Desvio</small><b>'+pp(i.gap)+'</b></div><div><small>Vs. semana anterior</small><b>'+pp(i.delta)+'</b></div></div></article>';}).join('')+'</div>';}
  else if(s.type==='vaps'){body='<div class="ffb-simple-list">'+items.map(i=>{const meta=[];if(i.reference)meta.push('Ref. '+esc(i.reference));if(i.sku)meta.push('SKU '+esc(i.sku));if(Number(i.allocation||0))meta.push('Alocação '+esc(i.allocation));if(Number(i.actual||0))meta.push('Real '+esc(i.actual));if(Number(i.pending||0))meta.push('Pendente '+esc(i.pending));if(Number(i.secondary_allocation||0))meta.push('2.ª alocação ITMI '+esc(i.secondary_allocation));if(i.status)meta.push(esc(i.status));return '<div class="ffb-simple-item"><strong>'+esc(i.name)+'</strong>'+(meta.length?'<br><small>'+meta.join(' · ')+'</small>':'')+'</div>';}).join('')+'</div>';}
  else {const textItems=items.length?items:(c.text?[c.text]:[]);body='<div class="ffb-simple-list">'+textItems.map(i=>'<div class="ffb-simple-item">'+esc(typeof i==='string'?i:(i.title||i.name||JSON.stringify(i)))+'</div>').join('')+'</div>';}
  const note=s.scope==='context'&&s.scope_note?'<div class="ffb-context-note">'+esc(s.scope_note)+'</div>':'';return '<article class="ffb-section '+(s.scope==='context'?'is-context':'')+'"><h5>'+esc(s.title)+'</h5>'+note+body+'</article>';}
 function retailerGroupsHtml(sections){if(!sections.length)return'<div class="ffb-panel-empty">Não existe conteúdo nesta área.</div>';const groups={};sections.forEach(s=>{const key=s.retailer_label||'Geral';(groups[key]||(groups[key]=[])).push(s)});const ordered=Object.entries(groups).sort((a,b)=>{const ar=a[1].some(x=>x.is_relevant!==false),br=b[1].some(x=>x.is_relevant!==false);return ar===br?0:(ar?-1:1)});return ordered.map(([label,rows],idx)=>{const relevant=rows.some(x=>x.is_relevant!==false),note=!relevant&&mode==='team'?'<div class="ffb-context-note">Contexto adicional do briefing. Esta insígnia não foi identificada nas tuas lojas atuais.</div>':'';return '<details class="ffb-retailer-accordion '+(!relevant?'is-context':'')+'" '+(idx===0?'open':'')+'><summary><span>'+esc(label)+'</span><small>'+(relevant?'Foco operacional':'Contexto')+' · '+rows.length+' secção(ões)</small></summary><div class="ffb-retailer-content">'+note+'<div class="ffb-section-grid">'+rows.map(sectionHtml).join('')+'</div></div></details>'}).join('')}
 function storesPanelHtml(items){if(!items||!items.length)return'<div class="ffb-panel-empty">Este briefing não contém instruções específicas por loja.</div>';const focus=items.filter(i=>i.scope==='assigned'),context=mode==='client'?items.filter(i=>!focus.includes(i)):[]; /* 9DL route-only spaces on operative */const renderGroup=(rows,title,note,contextMode)=>{if(!rows.length)return'';const retailers={};rows.forEach(i=>{const retailer=i.retailer_label||'Geral';const storeKey=(i.location_id?('id-'+i.location_id):('ext-'+i.external_store_name));retailers[retailer]||(retailers[retailer]={});const g=retailers[retailer][storeKey]||(retailers[retailer][storeKey]={name:i.location_name||i.external_store_name,assigned:false,items:[]});g.assigned=g.assigned||i.scope==='assigned';g.items.push(i)});return '<div class="ffb-store-scope-block"><h5>'+esc(title)+'</h5>'+(note?'<div class="ffb-context-note">'+esc(note)+'</div>':'')+Object.entries(retailers).map(([retailer,stores],idx)=>'<details class="ffb-retailer-accordion '+(contextMode?'is-context':'')+'" '+(idx===0&&!contextMode?'open':'')+'><summary><span>'+esc(retailer)+'</span><small>'+Object.keys(stores).length+' loja(s)</small></summary><div class="ffb-retailer-content"><div class="ffb-store-list">'+Object.values(stores).map(g=>'<div class="ffb-store-card '+(g.assigned?'assigned':'context')+'"><h5>'+esc(g.name)+(g.assigned?'<span class="ffb-store-badge">Na tua rota</span>':'<span class="ffb-store-badge context">'+(g.items.some(i=>i.scope==='briefing_only')?'Só briefing':'Informação adicional')+'</span>')+'</h5>'+g.items.map(i=>'<div class="ffb-store-item"><strong>'+esc(i.title)+'</strong><br><small>'+esc(typeLabels[i.type]||i.type)+(i.valid_from?' · '+fmtDate(i.valid_from)+' a '+fmtDate(i.valid_to):'')+'</small>'+(i.scope_note?'<div class="ffb-context-note">'+esc(i.scope_note)+'</div>':'')+(detailsText(i.details)?'<div>'+detailsText(i.details)+'</div>':'')+'</div>').join('')+'</div>').join('')+'</div></div></details>').join('')+'</div>'};if(mode==='client')return renderGroup(items,'Todas as instruções de loja','Inclui também designações ainda por associar no BO.',false);return focus.length?renderGroup(focus,'Nas tuas lojas desta semana','Apenas as lojas presentes na tua rota nesta semana.',false):'<div class="ffb-panel-empty">Não existem instruções deste tipo associadas às lojas da tua rota. As restantes ficam disponíveis no Backoffice.</div>' /* 9DL mobile records */}
 function clientKpis(s){if(mode!=='client')return'';s=s||{};return '<div class="ffb-client-kpis">'+[['Destinatários',s.recipients||0],['Visualizaram',s.viewed||0],['Confirmaram',s.acknowledged||0],['Pendentes',s.pending||0],['Taxa confirmação',(s.ack_rate||0)+'%']].map(x=>'<div class="ffb-client-kpi"><span>'+x[0]+'</span><strong>'+x[1]+'</strong></div>').join('')+'</div>';}
 function evidencePanelHtml(rows){if(mode!=='client')return'';if(!Array.isArray(rows)||!rows.length)return'<div class="ffb-panel-empty">A prova individual ficará disponível quando existirem destinatários.</div>';return '<div class="ffb-table-wrap ffb-evidence-table"><table><thead><tr><th>Operativo</th><th>Primeira visualização</th><th>Última visualização</th><th>Confirmação</th><th>Lojas</th></tr></thead><tbody>'+rows.map(r=>'<tr><td><strong>'+esc(r.display_name)+'</strong></td><td>'+fmtDateTime(r.first_viewed_at)+'</td><td>'+fmtDateTime(r.last_viewed_at)+'</td><td>'+(r.acknowledged_at?'<span class="ffb-evidence-ok">Confirmada em '+fmtDateTime(r.acknowledged_at)+'</span>':'<span class="ffb-evidence-pending">Pendente</span>')+'</td><td>'+esc(r.location_count||0)+'</td></tr>').join('')+'</tbody></table></div>';}
 function aiSummaryBanner(b){const ai=b.ai_copilot||{};if(!ai.available)return'';const rows=Array.isArray(ai.operational_summary)?ai.operational_summary.filter(Boolean):[];if(!rows.length&&ai.summary)rows.push(ai.summary);return '<div class="ffb-ai-banner"><div class="ffb-ai-banner-head"><strong>Resumo do Briefing AI Copilot</strong><span class="ffb-ai-badge">'+esc(ai.provider||'IA FieldFlow')+'</span></div>'+(ai.stale?'<div class="ffb-ai-stale">A análise está desatualizada face à última revisão do briefing.</div>':'')+'<div class="ffb-ai-summary-list">'+rows.slice(0,6).map(x=>'<div>'+esc(x)+'</div>').join('')+'</div></div>';}
 function aiPanelHtml(b){const ai=b.ai_copilot||{};if(!ai.available)return'<div class="ffb-panel-empty">Este briefing não tem uma análise de IA guardada.</div>';const audit=ai.audit||{},issues=Array.isArray(audit.issues)?audit.issues:[],changes=ai.changes||{},changeItems=Array.isArray(changes.items)?changes.items:[],statusLabels={good:'Pronto',warning:'Atenção',critical:'Crítico'},changeLabels={new:'Novo',removed:'Removido',changed:'Alterado'};return '<div class="ffb-ai-panel-grid"><section class="ffb-ai-panel-card"><h5>Leitura operacional</h5>'+aiSummaryBanner(b)+'<div class="ffb-ai-score-row"><span class="ffb-ai-score-circle">'+esc(audit.score||0)+'</span><div><strong>Qualidade da importação</strong><small>'+esc(statusLabels[audit.status]||'Atenção')+' · análise em '+fmtDateTime(ai.generated_at)+'</small></div></div><div class="ffb-ai-issues">'+issues.slice(0,8).map(i=>'<div class="ffb-ai-issue '+esc(i.severity||'info')+'"><strong>'+esc(i.title||'Alerta')+'</strong><small>'+esc(i.detail||'')+'</small></div>').join('')+'</div></section><section class="ffb-ai-panel-card"><h5>Alterações face à semana anterior</h5><p>'+esc(changes.headline||'Sem briefing anterior para comparação.')+'</p><div class="ffb-ai-changes">'+changeItems.slice(0,12).map(i=>'<div class="ffb-ai-change"><span class="ffb-change-chip '+esc(i.type||'changed')+'">'+esc(changeLabels[i.type]||'Alterado')+'</span><strong>'+esc(i.label||'Alteração')+'</strong><small>'+esc(i.detail||'')+'</small></div>').join('')+'</div></section></div>';}
 function priorityHighlights(sections){const rows=[];const ordered=[...sections].sort((a,b)=>(a.is_relevant===false)-(b.is_relevant===false));ordered.filter(s=>['focus','actions','information','leaflets','spaces_summary'].includes(s.type)).forEach(s=>{const items=Array.isArray(s.content?.items)?s.content.items:[];items.forEach(i=>{if(rows.length<6)rows.push(typeof i==='string'?i:(i.title||i.name||''))})});return rows.filter(Boolean)}
 function executionPanelHtml(b){
  const ex=b.execution||{},stats=ex.stats||{},qs=Array.isArray(ex.questions)?ex.questions:[];
  const kpis=[['Perguntas',stats.questions||qs.length],['Respostas atuais',stats.answers||0],['Implementadas',stats.conforming||0],['Não implementadas',stats.non_conforming||0]];
  const storeScope=q=>{const names=Array.isArray(q.location_names)?q.location_names:[],count=Number(q.store_count||names.length||0),scope=q.target_scope_label||'Âmbito da pergunta';if(count===1&&names[0])return names[0]+' · '+scope;if(mode==='team')return count+' loja(s) no teu âmbito · '+scope;return count+' loja(s) alvo · '+scope};
  const labels={implemented:'Implementado',attention:'Não implementado',not_implemented:'Não implementado',partial:'Parcial',pending:'Pendente',not_applicable:'Não aplicável',answered:'Respondido'};
  const stateLabel=q=>labels[String(q.execution_state||'pending')]||'Pendente';
  const stateSummary=q=>{const c=q.execution_counts||{},parts=[];if(Number(c.implemented||0))parts.push(Number(c.implemented)+' implementada(s)');if(Number(c.not_implemented||0))parts.push(Number(c.not_implemented)+' não implementada(s)');if(Number(c.pending||0))parts.push(Number(c.pending)+' pendente(s)');if(Number(c.not_applicable||0))parts.push(Number(c.not_applicable)+' N/A');return parts.join(' · ')};
  const normalizeSearch=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  const locationStates=q=>{const rows=Array.isArray(q.location_states)?q.location_states:[];if(!rows.length)return '';return '<details class="ffb-exec-store-details" data-exec-stores><summary>Ver lojas e estado · '+rows.length+'</summary><div class="ffb-exec-store-panel"><input class="ffb-exec-store-search" type="search" placeholder="Pesquisar loja, resposta ou estado" data-exec-store-search><div class="ffb-exec-store-list">'+rows.map(row=>{const state=String(row.state||'pending'),stateText=labels[state]||'Pendente',name=row.location_name||('Loja #'+row.location_id),answer=row.answer||'',search=normalizeSearch(name+' '+stateText+' '+answer);return '<div class="ffb-exec-store-row" data-exec-store-row data-search="'+esc(search)+'"><strong>'+esc(name)+'</strong><span class="ffb-exec-store-badge is-'+esc(state)+'">'+esc(stateText)+'</span>'+(answer?'<small>Resposta: '+esc(answer)+'</small>':'')+(row.submitted_at?'<small>'+esc(fmtDateTime(row.submitted_at))+'</small>':'')+'</div>'}).join('')+'</div><small class="ffb-exec-store-empty" data-exec-store-empty hidden>Nenhuma loja corresponde à pesquisa.</small></div></details>'};
  return '<div class="ffb-overview-grid">'+kpis.map(x=>'<div class="ffb-overview-card"><span>'+x[0]+'</span><strong>'+x[1]+'</strong></div>').join('')+'</div><div class="ffb-summary-panel"><h5>Perguntas de execução no formulário</h5><p>O estado é calculado pela resposta mais recente de cada loja alvo. A lista abaixo mostra exatamente onde cada pergunta está ativa, incluindo lojas da carteira do projeto que não estejam mapeadas no ficheiro semanal, quando esse for o âmbito escolhido.</p>'+(qs.length?'<div class="ffb-simple-list">'+qs.map(q=>'<div class="ffb-simple-item"><strong>'+esc(q.label||'Pergunta')+'</strong>'+(q.category?'<span class="ffb-exec-category">'+esc(q.category)+'</span>':'<span class="ffb-exec-category is-pending">Categoria por confirmar</span>')+'<small>'+esc(q.form_title||'Qualquer formulário')+' · '+esc(storeScope(q))+(q.required?' · Obrigatória':'')+'</small><small><strong>'+esc(stateLabel(q))+'</strong>'+(stateSummary(q)?' · '+esc(stateSummary(q)):'')+'</small>'+locationStates(q)+'</div>').join('')+'</div>':'<div class="ffb-panel-empty">Ainda não existem perguntas de execução configuradas para este briefing.</div>')+'</div>'
 }

 function tabConfig(b){const sections=b.sections||[],stores=b.store_items||[];const priorities=sections.filter(s=>!['promotions','vaps','share_space','cardex'].includes(s.type));const promotions=sections.filter(s=>s.type==='promotions');const vaps=sections.filter(s=>s.type==='vaps');const share=sections.filter(s=>s.type==='share_space');const cardex=sections.filter(s=>s.type==='cardex');const spaces=stores.filter(i=>i.type==='space'),assortment=stores.filter(i=>i.type==='assortment'),otherStores=stores.filter(i=>!['space','assortment'].includes(i.type));const configs=[
  {key:'summary',label:'Resumo',count:'',html:summaryHtml(b,priorities,promotions,vaps,share,cardex,stores)},
  {key:'execution',label:'Execução',count:Number(b.execution?.stats?.questions||0),html:executionPanelHtml(b)},
  {key:'priorities',label:'Prioridades',count:priorities.reduce((n,s)=>n+itemCount(s),0),html:retailerGroupsHtml(priorities)},
  {key:'promotions',label:'Promoções',count:promotions.reduce((n,s)=>n+itemCount(s),0),html:retailerGroupsHtml(promotions)},
  {key:'spaces',label:'Espaços centralizados',count:spaces.length,html:storesPanelHtml(spaces)},
  {key:'assortment',label:'Sortido por loja',count:assortment.length,html:storesPanelHtml(assortment)},
  {key:'stores',label:'Outras instruções',count:otherStores.length,html:storesPanelHtml(otherStores)},
  {key:'vaps',label:'VAPs',count:vaps.reduce((n,s)=>n+itemCount(s),0),html:retailerGroupsHtml(vaps)},
  {key:'share',label:'Share Space',count:share.reduce((n,s)=>n+itemCount(s),0),html:retailerGroupsHtml(share)},
  {key:'cardex',label:'Cardex',count:cardex.reduce((n,s)=>n+itemCount(s),0),html:retailerGroupsHtml(cardex)}
 ];if(b.ai_copilot&&b.ai_copilot.available)configs.splice(1,0,{key:'ai',label:'Copiloto IA',count:'',html:aiPanelHtml(b)});if(mode==='client')configs.push({key:'evidence',label:'Evidência',count:Array.isArray(b.evidence)?b.evidence.length:0,html:evidencePanelHtml(b.evidence)});return configs.filter(t=>t.key==='summary'||t.key==='ai'||t.key==='evidence'||Number(t.count)>0)}
 function summaryHtml(b,priorities,promotions,vaps,share,cardex,stores){const sections=b.sections||[],scope=b.scope||{};const scopeBanner=mode==='team'?'<div class="ffb-scope-banner"><strong>Briefing da tua rota:</strong> '+esc(scope.assigned_items||0)+' instrução(ões) por loja na tua rota. '+(Number(scope.excluded_store_items||0)?esc(scope.excluded_store_items)+' instrução(ões) de outras lojas foram reservadas para o Backoffice.':'Só aparecem lojas da tua rota.')+'</div>':''; /* 9DL */const retailers=new Set(sections.map(s=>s.retailer_label).filter(Boolean));(stores||[]).forEach(i=>{if(i.retailer_label)retailers.add(i.retailer_label)});const spaces=(stores||[]).filter(i=>i.type==='space').length,assortment=(stores||[]).filter(i=>i.type==='assortment').length;const counts={priorities:priorities.reduce((n,s)=>n+itemCount(s),0),promotions:promotions.reduce((n,s)=>n+itemCount(s),0),spaces,assortment,vaps:vaps.reduce((n,s)=>n+itemCount(s),0),share:share.reduce((n,s)=>n+itemCount(s),0),cardex:cardex.reduce((n,s)=>n+itemCount(s),0)};const highlights=priorityHighlights(sections);const links=[['priorities','Prioridades',counts.priorities],['promotions','Promoções',counts.promotions],['spaces','Espaços centralizados',counts.spaces],['assortment','Sortido por loja',counts.assortment],['vaps','VAPs',counts.vaps],['share','Share Space',counts.share],['cardex','Cardex',counts.cardex]].filter(x=>x[2]>0);return clientKpis(b.stats)+scopeBanner+aiSummaryBanner(b)+'<div class="ffb-overview-grid">'+[['Insígnias',retailers.size],['Promoções',counts.promotions],['Espaços',counts.spaces],['KPI Share Space',counts.share],['Produtos no cardex',counts.cardex]].map(x=>'<div class="ffb-overview-card"><span>'+x[0]+'</span><strong>'+x[1]+'</strong></div>').join('')+'</div><div class="ffb-summary-layout"><div class="ffb-summary-panel"><h5>O essencial desta semana</h5>'+(highlights.length?'<div class="ffb-priority-list">'+highlights.map(x=>'<div class="ffb-priority-item">'+esc(x)+'</div>').join('')+'</div>':'<p>Consulta as áreas disponíveis para veres o detalhe operacional deste briefing.</p>')+'</div><div class="ffb-summary-panel"><h5>Navegação rápida</h5><div class="ffb-content-map">'+links.map(x=>'<button type="button" class="ffb-content-link" data-open-tab="'+x[0]+'"><strong>'+x[1]+'</strong><small>'+x[2]+' item(ns)</small></button>').join('')+'</div></div></div>'}
 function briefingHtml(b){const acknowledged=b.read&&b.read.acknowledged_at,canAck=mode==='team'&&b.can_acknowledge!==false;const stateLabel=mode==='client'?'Comunicação registada':(canAck?(acknowledged?'Leitura confirmada':'Confirmação pendente'):'Vista de gestão');const tabs=tabConfig(b);return '<article class="ffb-briefing" data-id="'+b.id+'"><header class="ffb-briefing-head"><div><span class="ffb-week">W'+b.week_no+' · '+b.year_no+' · v'+b.version_no+'</span><h4>'+esc(b.title)+'</h4><p>Válido de '+fmtDate(b.valid_from)+' a '+fmtDate(b.valid_to)+'</p><small>Publicado em '+fmtDateTime(b.published_at)+(b.ai_copilot&&b.ai_copilot.available?' · IA '+esc(b.ai_copilot.provider||'FieldFlow'):'')+'</small></div><div class="ffb-read-state"><span>'+stateLabel+'</span><small>'+tabs.length+' áreas organizadas para consulta rápida</small></div></header><div class="ffb-briefing-body"><div class="ffb-tabs-shell"><div class="ffb-tabs" role="tablist">'+tabs.map((t,idx)=>'<button type="button" class="ffb-tab '+(idx===0?'active':'')+'" data-tab="'+t.key+'" role="tab" aria-selected="'+(idx===0?'true':'false')+'">'+t.label+(t.count!==''?'<span class="ffb-tab-count">'+t.count+'</span>':'')+'</button>').join('')+'</div></div>'+tabs.map((t,idx)=>'<section class="ffb-tab-panel '+(idx===0?'active':'')+'" data-panel="'+t.key+'" role="tabpanel">'+t.html+'</section>').join('')+(canAck?'<div class="ffb-actions-row"><button class="ffb-front-btn '+(acknowledged?'confirmed':'')+'" data-ack="'+b.id+'" '+(acknowledged?'disabled':'')+'>'+(acknowledged?'Leitura confirmada':'Confirmar leitura')+'</button></div>':'')+'</div></article>';}
 function activateTab(card,key){card.querySelectorAll('[data-tab]').forEach(btn=>{const active=btn.dataset.tab===key;btn.classList.toggle('active',active);btn.setAttribute('aria-selected',active?'true':'false')});card.querySelectorAll('[data-panel]').forEach(panel=>panel.classList.toggle('active',panel.dataset.panel===key));const btn=card.querySelector('[data-tab="'+key+'"]');if(btn)btn.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'});}
 function bind(){root.querySelectorAll('.ffb-briefing').forEach(card=>{card.querySelectorAll('[data-tab]').forEach(btn=>btn.addEventListener('click',()=>activateTab(card,btn.dataset.tab)));card.querySelectorAll('[data-open-tab]').forEach(btn=>btn.addEventListener('click',()=>activateTab(card,btn.dataset.openTab)));});root.querySelectorAll('[data-ack]').forEach(btn=>btn.addEventListener('click',async()=>{btn.disabled=true;btn.textContent='A confirmar...';try{await req(api+'briefings/'+btn.dataset.ack+'/ack',{method:'POST'});btn.classList.add('confirmed');btn.textContent='Leitura confirmada';const state=btn.closest('.ffb-briefing')?.querySelector('.ffb-read-state span');if(state)state.textContent='Leitura confirmada';}catch(e){btn.disabled=false;btn.textContent='Confirmar leitura';status.textContent=e.message;}}));root.querySelectorAll('.ffb-cardex-search').forEach(inp=>inp.addEventListener('input',()=>{const q=inp.value.trim().toLowerCase();inp.parentElement.querySelectorAll('[data-search]').forEach(row=>row.style.display=!q||row.dataset.search.includes(q)?'':'none'); /* 9DL */}));root.querySelectorAll('[data-exec-store-search]').forEach(inp=>inp.addEventListener('input',()=>{const q=String(inp.value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLowerCase(),details=inp.closest('[data-exec-stores]'),rows=details?Array.from(details.querySelectorAll('[data-exec-store-row]')):[];let visible=0;rows.forEach(row=>{const show=!q||String(row.dataset.search||'').includes(q);row.style.display=show?'':'none';if(show)visible++;});const empty=details?details.querySelector('[data-exec-store-empty]'):null;if(empty)empty.hidden=visible>0;}));}
 function render(data,fromCache=false){const rows=data.briefings||[];status.textContent=rows.length?(fromCache?'Conteúdo guardado no dispositivo. A sincronizar...':rows.length+' briefing(s) disponível(eis).'):'Não existem briefings publicados para este âmbito.';list.innerHTML=rows.length?rows.map(briefingHtml).join(''):'<div class="ffb-front-empty">Quando um briefing for publicado, aparecerá aqui já filtrado para a operação certa.</div>';bind();if(mode==='team')rows.forEach(b=>{if(b.can_acknowledge!==false&&!(b.read&&b.read.first_viewed_at))req(api+'briefings/'+b.id+'/view',{method:'POST'}).catch(()=>{});});notifyReact();}
 async function load(){try{status.textContent='A atualizar briefings...';const scope=currentScope();const p=new URLSearchParams({client_id:scope.client_id||'',project_id:scope.project_id||''});const url=api+(mode==='team'?'briefings/mine?':'briefings/client?')+p.toString();const data=await req(url);try{localStorage.setItem(cacheKey(),JSON.stringify({version:2,user_id:cacheUser,stored_at:Date.now(),payload:data}));}catch(_){}render(data,false);}catch(e){status.textContent=e.message||'Não foi possível atualizar.';notifyReact();}}
 root.querySelector('[data-refresh]')?.addEventListener('click',load);document.addEventListener('routespro:panel-open',ev=>{if((ev.detail?.panel||'')==='briefings')load();});document.addEventListener('routespro:scope-change',ev=>{const d=ev.detail||{};if(typeof d.client_id!=='undefined')root.dataset.clientId=d.client_id||'';if(typeof d.project_id!=='undefined')root.dataset.projectId=d.project_id||'';load();});if(mode==='client'&&parentPortal){const c=parentPortal.querySelector('#rpcp-client'),p=parentPortal.querySelector('#rpcp-project');c?.addEventListener('change',()=>setTimeout(load,30));p?.addEventListener('change',()=>setTimeout(load,30));currentScope();}
 try{const cached=JSON.parse(localStorage.getItem(cacheKey())||'null');if(cached&&cached.version===2&&String(cached.user_id)===cacheUser&&Number(cached.stored_at||0)>Date.now()-cacheTtl&&cached.payload)render(cached.payload,true);}catch(_){}setTimeout(load,80);
})();
</script><?php }
